<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:12px}.head{border-bottom:3px solid #1688c4;padding-bottom:14px;margin-bottom:25px}.right{float:right;text-align:right}h1{margin:0;color:#0b4f78}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{padding:10px;border:1px solid #d8e0ea;text-align:left}th{background:#eef5fa}.total{text-align:right;font-size:16px}.paid{color:#07865f;font-weight:bold}.muted{color:#667085}</style></head><body><div class="head"><div class="right"><b>{{ $receipt?'PAYMENT RECEIPT':'SUBSCRIPTION INVOICE' }}</b><br>{{ $invoice->number }}</div><h1>{{ config('app.name','EyeClinic') }}</h1><span class="muted">Platform subscription billing</span></div><h2>{{ $invoice->clinic->name }}</h2><p>{{ $invoice->clinic->billing_email }}</p><table><tr><th>Billing period</th><th>Due date</th><th>Status</th></tr><tr><td>{{ $invoice->period_start->format('d M Y') }} – {{ $invoice->period_end->format('d M Y') }}</td><td>{{ $invoice->due_date->format('d M Y') }}</td><td>{{ strtoupper($invoice->status) }}</td></tr></table><table><tr><th>Description</th><th>Subtotal</th><th>Tax</th><th>Total</th></tr>@if($invoice->lines->isNotEmpty())@foreach($invoice->lines as $line)<tr><td>{{ $line->description }}</td><td>{{ $invoice->currency }} {{ number_format((float)$line->amount,2) }}</td><td></td><td></td></tr>@endforeach<tr><td><b>Total</b></td><td>{{ $invoice->currency }} {{ number_format((float)$invoice->subtotal,2) }}</td><td>{{ number_format((float)$invoice->tax,2) }}</td><td>{{ number_format((float)$invoice->total,2) }}</td></tr>@else<tr><td>{{ $invoice->notes?:'Clinic software subscription' }}</td><td>{{ $invoice->currency }} {{ number_format((float)$invoice->subtotal,2) }}</td><td>{{ number_format((float)$invoice->tax,2) }}</td><td>{{ number_format((float)$invoice->total,2) }}</td></tr>@endif</table><p class="total">Paid: <span class="paid">{{ $invoice->currency }} {{ number_format((float)$invoice->amount_paid,2) }}</span><br>Balance: {{ $invoice->currency }} {{ number_format($invoice->balance(),2) }}</p>@if($receipt)<h3>Payments</h3><table><tr><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th></tr>@foreach($invoice->payments as $payment)<tr><td>{{ $payment->paid_at->format('d M Y H:i') }}</td><td>{{ ucwords(str_replace('_',' ',$payment->method)) }}</td><td>{{ $payment->reference??'—' }}</td><td>{{ $invoice->currency }} {{ number_format((float)$payment->amount,2) }}</td></tr>@endforeach</table>@endif</body></html>
